233:   <script>
234:     (() => {
235:       const canvas = document.getElementById("screen");
236:       const ctx = canvas.getContext("2d");
237:       const overlay = document.getElementById("overlay");
238:       const startBtn = document.getElementById("start");
239:       const healthLabel = document.getElementById("health");
