247:       const W = canvas.width, H = canvas.height;
248:       const FOV = Math.PI / 3;
249:       const keys = {};
250:       const mobile = {
251:         moveX: 0, moveY: 0,
252:         lookX: 0, lookY: 0,
253:         fired: false
254:       };
255: 
256:       const map = [
257:         "111111111111",
258:         "100000000001",
259:         "100010010001",
260:         "100010000001",
261:         "100000100001",
262:         "101000000101",
263:         "100000000001",
264:         "100100010001",
265:         "100000000001",
266:         "100010000001",
267:         "100000000001",
268:         "111111111111"
269:       ];
270: 
271:       const mapW = map[0].length;
272:       const mapH = map.length;
273: 
274:       const player = {
275:         x: 2.5,
276:         y: 2.5,
277:         angle: 0,
278:         health: 100
279:       };
280: 
281:       let enemies = [];
282:       let running = false;
283:       let score = 0;
284:       let lastTime = 0;
285:       let shotFlash = 0;
286:       let damageFlash = 0;
287:       let depthBuffer = new Float32Array(W);
288: 
289:       function resetGame() {
290:         player.x = 2.5;
291:         player.y = 2.5;
292:         player.angle = 0;
293:         player.health = 100;
294:         score = 0;
295:         shotFlash = 0;
296:         damageFlash = 0;
297:         enemies = [
298:           { x: 8.5, y: 2.5, hp: 2 },
299:           { x: 9.5, y: 5.5, hp: 2 },
300:           { x: 3.5, y: 8.5, hp: 2 },
301:           { x: 8.5, y: 9.5, hp: 2 },
302:           { x: 6.5, y: 6.5, hp: 2 },
303:           { x: 2.5, y: 10.0, hp: 2 }
304:         ];
305:         updateHud();
306:       }
307: 
308:       function wallAt(x, y) {
309:         const mx = Math.floor(x);
310:         const my = Math.floor(y);
311:         return mx < 0 || my < 0 || mx >= mapW || my >= mapH || map[my][mx] === "1";
312:       }
313: 
314:       function castRay(angle) {
315:         let distance = 0;
316:         const dx = Math.cos(angle), dy = Math.sin(angle);
317:         while (distance < 20) {
318:           distance += 0.025;
319:           const x = player.x + dx * distance;
320:           const y = player.y + dy * distance;
321:           if (wallAt(x, y)) return distance;
322:         }
323:         return 20;
324:       }
325: 
326:       function updateHud() {
327:         healthLabel.textContent = `HEALTH ${Math.ceil(player.health)}`;
328:         scoreLabel.textContent = `THUGS ${score}`;
329:       }
330: 
331:       function movePlayer(dx, dy) {
332:         const radius = 0.18;
333:         const nextX = player.x + dx;
334:         const nextY = player.y + dy;
335: 
336:         if (!wallAt(nextX + Math.sign(dx || 1) * radius, player.y)) {
337:           player.x = nextX;
338:         }
339:         if (!wallAt(player.x, nextY + Math.sign(dy || 1) * radius)) {
340:           player.y = nextY;
341:         }
342:       }
343: 
344:       function updateMovement(dt) {
345:         const keyboardMoveX =
346:           (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0);
347:         const keyboardMoveY =
348:           (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0);
349: 
350:         const moveX = keyboardMoveX + mobile.moveX;
351:         const moveY = keyboardMoveY + mobile.moveY;
352: 
353:         const moveLen = Math.hypot(moveX, moveY) || 1;
354:         const normalizedX = moveX / moveLen;
355:         const normalizedY = moveY / moveLen;
356: 
357:         if (moveLen > 0.1) {
358:           const s = 2.4 * dt;
359:           const forwardX = Math.cos(player.angle) * normalizedY;
360:           const forwardY = Math.sin(player.angle) * normalizedY;
361:           const strafeX = Math.cos(player.angle + Math.PI / 2) * normalizedX;
362:           const strafeY = Math.sin(player.angle + Math.PI / 2) * normalizedX;
363: 
364:           movePlayer((forwardX + strafeX) * s, (forwardY + strafeY) * s);
365:         }
366:       }
367: 
368:       function applyLookInput() {
369:         const lookX = mobile.lookX;
370:         const lookY = mobile.lookY;
371: 
372:         if (Math.abs(lookX) > 0.08 || Math.abs(lookY) > 0.08) {
373:           player.angle += lookX * 0.055;
374:         }
375:       }
376: 
377:       function renderWorld() {
378:         const sky = ctx.createLinearGradient(0, 0, 0, H * 0.5);
379:         sky.addColorStop(0, "#4f5d74");
380:         sky.addColorStop(1, "#d4c9a8");
381:         ctx.fillStyle = sky;
382:         ctx.fillRect(0, 0, W, H * 0.5);
383: 
384:         const floor = ctx.createLinearGradient(0, H * 0.5, 0, H);
385:         floor.addColorStop(0, "#5d564f");
386:         floor.addColorStop(1, "#1e1e22");
387:         ctx.fillStyle = floor;
388:         ctx.fillRect(0, H / 2, W, H / 2);
389: 
390:         for (let x = 0; x < W; x++) {
391:           const rayAngle = player.angle + Math.atan((2 * x / W - 1) * Math.tan(FOV / 2));
392:           const dist = castRay(rayAngle);
393:           const corrected = Math.max(0.01, dist * Math.cos(rayAngle - player.angle));
394:           depthBuffer[x] = corrected;
395:           const wallH = Math.min(H * 1.8, H / corrected);
396:           const top = (H - wallH) / 2;
397:           const shade = Math.max(30, 170 - corrected * 18);
398:           const stripe = ((x / 8) % 2) ? 0 : 10;
399:           ctx.fillStyle = `rgb(${shade + stripe},${shade + stripe},${shade - 8})`;
400:           ctx.fillRect(x, top, 1, wallH);
401:         }
402: 
403:         renderEnemies();
404:       }
405: 
406:       function renderEnemies() {
407:         const visible = enemies
408:           .map(enemy => {
409:             let angle = Math.atan2(enemy.y - player.y, enemy.x - player.x) - player.angle;
410:             while (angle > Math.PI) angle -= Math.PI * 2;
411:             while (angle < -Math.PI) angle += Math.PI * 2;
412: 
413:             return {
414:               ...enemy,
415:               angle,
416:               dist: Math.hypot(enemy.x - player.x, enemy.y - player.y)
417:             };
418:           })
419:           .filter(enemy => Math.abs(enemy.angle) < FOV / 2 + 0.18)
420:           .sort((a, b) => b.dist - a.dist);
421: 
422:         for (const enemy of visible) {
423:           const screenX = W / 2 + Math.tan(enemy.angle) * (W / 2) / Math.tan(FOV / 2);
424:           const size = Math.min(H * 0.8, H / enemy.dist * 0.72);
425:           const left = screenX - size * 0.25;
426:           const top = H / 2 - size * 0.48;
427: 
428:           const centerColumn = Math.max(0, Math.min(W - 1, Math.floor(screenX)));
429:           if (enemy.dist > depthBuffer[centerColumn] + 0.15) continue;
430: 
431:           ctx.fillStyle = "#121416";
432:           ctx.fillRect(left + size * 0.10, top + size * 0.30, size * 0.30, size * 0.55);
433:           ctx.beginPath();
434:           ctx.arc(screenX, top + size * 0.20, size * 0.15, 0, Math.PI * 2);
435:           ctx.fill();
436: 
437:           ctx.fillStyle = "#a14a3a";
438:           ctx.fillRect(left + size * 0.08, top + size * 0.48, size * 0.34, size * 0.12);
439: 
440:           ctx.fillStyle = "#e6e6e6";
441:           ctx.fillRect(screenX - size * 0.08, top + size * 0.17, size * 0.04, size * 0.035);
442:           ctx.fillRect(screenX + size * 0.04, top + size * 0.17, size * 0.04, size * 0.035);
443:         }
444:       }
445: 
446:       function shoot() {
447:         if (!running) return;
448:         shotFlash = 0.08;
449: 
450:         let target = null;
451:         let nearest = Infinity;
452: 
453:         for (const enemy of enemies) {
454:           let angle = Math.atan2(enemy.y - player.y, enemy.x - player.x) - player.angle;
455:           while (angle > Math.PI) angle -= Math.PI * 2;
456:           while (angle < -Math.PI) angle += Math.PI * 2;
457: 
458:           const dist = Math.hypot(enemy.x - player.x, enemy.y - player.y);
459:           const aimWindow = Math.atan(0.30 / Math.max(0.15, dist));
460: 
461:           if (Math.abs(angle) < aimWindow && dist < nearest) {
462:             target = enemy;
463:             nearest = dist;
464:           }
465:         }
466: 
467:         if (target) {
468:           target.hp -= 1;
469:           if (target.hp <= 0) {
470:             enemies = enemies.filter(e => e !== target);
471:             score++;
472:             updateHud();
473:             if (enemies.length === 0) {
474:               endGame("BLOCK CLEARED", "You cleared the block.");
475:             }
476:           }
477:         }
478:       }
479: 
480:       function endGame(title, message) {
481:         running = false;
482:         document.exitPointerLock?.();
483:         overlay.classList.remove("hidden");
484:         const panel = document.getElementById("panel");
485:         panel.innerHTML = `
486:           <h1>${title}</h1>
487:           <p class="small">${message}</p>
488:           <p class="small">You eliminated ${score} thug${score === 1 ? "" : "s"}.</p>
489:           <button id="start">PLAY AGAIN</button>
490:         `;
491:         document.getElementById("start").addEventListener("click", beginGame);
492:       }
493: 
494:       function beginGame() {
495:         resetGame();
496:         running = true;
497:         overlay.classList.add("hidden");
498:         canvas.requestPointerLock?.();
499:         lastTime = performance.now();
500:       }
501: 
502:       function updateEnemies(dt) {
503:         for (const enemy of enemies) {
504:           const dx = player.x - enemy.x;
505:           const dy = player.y - enemy.y;
506:           const dist = Math.hypot(dx, dy);
507: 
508:           if (dist > 0.7 && dist < 8) {
509:             const step = Math.min(0.75 * dt, dist * 0.08);
510:             const nx = enemy.x + (dx / dist) * step;
511:             const ny = enemy.y + (dy / dist) * step;
512: 
513:             if (!wallAt(nx, enemy.y)) enemy.x = nx;
514:             if (!wallAt(enemy.x, ny)) enemy.y = ny;
515:           } else if (dist <= 0.7) {
516:             player.health = Math.max(0, player.health - 16 * dt);
517:             damageFlash = 0.18;
518:             updateHud();
519: 
520:             if (player.health <= 0) {
521:               endGame("YOU'RE DOWN", "The block got the better of you.");
522:             }
523:           }
524:         }
525:       }
526: 
527:       function drawWeapon() {
528:         ctx.fillStyle = "#20242c";
529:         ctx.beginPath();
530:         ctx.moveTo(W * 0.40, H);
531:         ctx.lineTo(W * 0.44, H * 0.77);
532:         ctx.lineTo(W * 0.57, H * 0.77);
533:         ctx.lineTo(W * 0.62, H);
534:         ctx.fill();
535: 
536:         ctx.fillStyle = "#4c4f57";
537:         ctx.fillRect(W * 0.47, H * 0.73, W * 0.07, H * 0.13);
538: 
539:         if (shotFlash > 0) {
540:           ctx.fillStyle = "#ffd76a";
541:           ctx.beginPath();
542:           ctx.moveTo(W / 2, H * 0.69);
543:           ctx.lineTo(W / 2 - 24, H * 0.56);
544:           ctx.lineTo(W / 2, H * 0.60);
545:           ctx.lineTo(W / 2 + 24, H * 0.56);
546:           ctx.fill();
547:         }
548: 
549:         ctx.strokeStyle = "#ffffff";
550:         ctx.lineWidth = 2;
551:         ctx.beginPath();
552:         ctx.moveTo(W / 2 - 10, H / 2); ctx.lineTo(W / 2 - 3, H / 2);
553:         ctx.moveTo(W / 2 + 3, H / 2); ctx.lineTo(W / 2 + 10, H / 2);
554:         ctx.moveTo(W / 2, H / 2 - 10); ctx.lineTo(W / 2, H / 2 - 3);
555:         ctx.moveTo(W / 2, H / 2 + 3); ctx.lineTo(W / 2, H / 2 + 10);
556:         ctx.stroke();
557: 
558:         if (damageFlash > 0) {
559:           ctx.fillStyle = `rgba(210, 45, 32, ${damageFlash * 0.65})`;
560:           ctx.fillRect(0, 0, W, H);
561:         }
562:       }
563: 
564:       function update(dt) {
565:         if (!running) return;
566: 
567:         updateMovement(dt);
568:         applyLookInput();
569:         updateEnemies(dt);
570: 
571:         shotFlash = Math.max(0, shotFlash - dt);
572:         damageFlash = Math.max(0, damageFlash - dt);
573: 
574:         if (keys.ArrowLeft) player.angle -= 2.1 * dt;
575:         if (keys.ArrowRight) player.angle += 2.1 * dt;
576: 
577:         if (keys.Space || mobile.fired) {
578:           shoot();
579:           mobile.fired = false;
580:         }
581:       }
