583:       function frame(ts) {
584:         const dt = Math.min(0.04, (ts - lastTime) / 1000 || 0);
585:         lastTime = ts;
586:         update(dt);
587:         renderWorld();
588:         drawWeapon();
589:         requestAnimationFrame(frame);
590:       }
