592:       function clampStick(x, y) {
593:         const r = 34;
594:         const dist = Math.hypot(x, y);
595:         if (dist > r) {
596:           const angle = Math.atan2(y, x);
597:           x = Math.cos(angle) * r;
598:           y = Math.sin(angle) * r;
599:         }
600:         return { x, y };
601:       }
602: 
603:       function bindThumb(el, zone, inputKeyX, inputKeyY) {
604:         const center = () => {
605:           const rect = zone.getBoundingClientRect();
606:           return {
607:             x: rect.left + rect.width / 2,
608:             y: rect.top + rect.height / 2
609:           };
610:         };
611: 
612:         const onPointerDown = (e) => {
613:           e.preventDefault();
614:           zone.setPointerCapture?.(e.pointerId);
615:           const c = center();
616:           const dx = e.clientX - c.x;
617:           const dy = e.clientY - c.y;
618:           const pos = clampStick(dx, dy);
619:           el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;
620:           mobile[inputKeyX] = pos.x / 34;
621:           mobile[inputKeyY] = pos.y / 34;
622:         };
623: 
624:         const onPointerMove = (e) => {
625:           if (e.pointerType === "mouse" && e.buttons === 0) return;
626:           const c = center();
627:           const dx = e.clientX - c.x;
628:           const dy = e.clientY - c.y;
629:           const pos = clampStick(dx, dy);
