function bindThumb(el, zone, inputKeyX, inputKeyY) {
  const center = () => {
    const rect = zone.getBoundingClientRect();
    return {
      x: rect.left + rect.width / 2,
      y: rect.top + rect.height / 2
    };
  };

  const onPointerDown = (e) => {
    e.preventDefault();
    zone.setPointerCapture?.(e.pointerId);
    const c = center();
    const dx = e.clientX - c.x;
    const dy = e.clientY - c.y;
    const pos = clampStick(dx, dy);
    el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;
    mobile[inputKeyX] = pos.x / 34;
    mobile[inputKeyY] = pos.y / 34;
  };

  const onPointerMove = (e) => {
    if (e.pointerType === "mouse" && e.buttons === 0) return;
    const c = center();
    const dx = e.clientX - c.x;
    const dy = e.clientY - c.y;
    const pos = clampStick(dx, dy);
    el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;
    mobile[inputKeyX] = pos.x / 34;
    mobile[inputKeyY] = pos.y / 34;
  };

  const onPointerUp = () => {
    el.style.transform = "translate(-50%, -50%)";
    mobile[inputKeyX] = 0;
    mobile[inputKeyY] = 0;
  };

  zone.addEventListener("pointerdown", onPointerDown);
  zone.addEventListener("pointermove", onPointerMove);
  zone.addEventListener("pointerup", onPointerUp);
  zone.addEventListener("pointercancel", onPointerUp);
  zone.addEventListener("pointerleave", onPointerUp);
}

input.newString:
function bindThumb(el, zone, inputKeyX, inputKeyY) {
  let activePointerId = null;

  const updateStick = (e) => {
    const rect = zone.getBoundingClientRect();
    const dx = e.clientX - (rect.left + rect.width / 2);
    const dy = e.clientY - (rect.top + rect.height / 2);
    const pos = clampStick(dx, dy);
    el.style.left = `calc(50% + ${pos.x}px)`;
    el.style.top = `calc(50% + ${pos.y}px)`;
    mobile[inputKeyX] = pos.x / 34;
    // Pushing the movement stick up means moving forward.
    mobile[inputKeyY] = (inputKeyY === "moveY" ? -pos.y : pos.y) / 34;
  };

  const releaseStick = (e) => {
    if (e.pointerId !== activePointerId) return;
    activePointerId = null;
    el.style.left = "50%";
    el.style.top = "50%";
    mobile[inputKeyX] = 0;
    mobile[inputKeyY] = 0;
    if (zone.hasPointerCapture?.(e.pointerId)) {
      zone.releasePointerCapture(e.pointerId);
    }
  };

  zone.addEventListener("pointerdown", (e) => {
    if (activePointerId !== null) return;
    e.preventDefault();
    activePointerId = e.pointerId;
    zone.setPointerCapture?.(e.pointerId);
    updateStick(e);
  });

  zone.addEventListener("pointermove", (e) => {
    if (e.pointerId !== activePointerId) return;
    e.preventDefault();
    updateStick(e);
  });

  zone.addEventListener("pointerup", releaseStick);
  zone.addEventListener("pointercancel", releaseStick);
  zone.addEventListener("lostpointercapture", releaseStick);
}

